effect.shader:
void main() {
    vec2 uv = clamp(acScreenNorm.st, 0.0, 1.0);
    vec4 source = texture2DCv(inputImg.texture, uv);
    float amount = clamp(start / 100.0, 0.0, 0.49);
    float useCustomBounds = step(0.0001, abs(startA) + abs(endA - 1.0));
    float low = mix(amount, min(startA, endA), useCustomBounds);
    float high = mix(1.0 - amount, max(startA, endA), useCustomBounds);
    low = clamp(low, -0.5, 1.5);
    high = clamp(high, -0.5, 1.5);
    float useCustomAngle = step(0.0001, abs(angleA));
    float degrees = mix(angle, angleA, useCustomAngle);
    float radians = degrees * 0.01745329252;
    vec2 direction = normalize(vec2(cos(radians), -sin(radians)));
    float position = dot(acLayerNorm.st - vec2(0.5), direction) + 0.5;
    float feather = max(featherA / 100.0, 0.00001);
    float insideStart = smoothstep(low - feather, low + feather, position);
    float insideEnd = 1.0 - smoothstep(high - feather, high + feather, position);
    float inside = clamp(insideStart * insideEnd, 0.0, 1.0);
    float bars = 1.0 - inside;
    float barAlpha = clamp(colorbg.a * bars, 0.0, 1.0);
    vec3 outputRGB = mix(source.rgb, colorbg.rgb, barAlpha);
    float outputAlpha = source.a + barAlpha * (1.0 - source.a);
    gl_FragColor = vec4(outputRGB, outputAlpha);
}
